xhtml:div.xhtml:script:
(function () {
  "use strict";
  var endpoint = "https://ubg-site.pages.dev/app.html";
  var baseUrl = "https://ubg-site.pages.dev/";
  var frame = document.getElementById("nero-app");

  function showError() {
    frame.srcdoc = '<!doctype html><html><body style="margin:0;background:#050505;color:#fff;font:16px Arial,sans-serif;display:grid;place-items:center;height:100vh"><p>NERO could not load. Check your connection or browser permissions.</p></body></html>';
  }

  if (!window.fetch) {
    showError();
    return;
  }

  var controller = typeof AbortController !== "undefined"
    ? new AbortController()
    : null;
  var timer = window.setTimeout(function () {
    if (controller) controller.abort();
  }, 9000);

  window.fetch(endpoint, {
    method: "GET",
    mode: "cors",
    credentials: "omit",
    cache: "no-store",
    signal: controller ? controller.signal : undefined
  }).then(function (response) {
    if (!response.ok) throw new Error("HTTP " + response.status);
    return response.text();
  }).then(function (html) {
    window.clearTimeout(timer);
    if (typeof html !== "string" || !html.trim()) throw new Error("Empty response");
    var base = '<base href="' + baseUrl + '">';
    if (/<head(?:\\s[^>]*)?>/i.test(html)) {
      html = html.replace(/<head(?:\\s[^>]*)?>/i, function (tag) {
        return tag + base;
      });
    } else {
      html = '<!doctype html><html><head>' + base +
        '</head><body>' + html + '</body></html>';
    }
    frame.srcdoc = html;
  }).catch(function () {
    window.clearTimeout(timer);
    showError();
  });
})();
